// Legal pages: shared sections written into each site's page, the fields they take, the date stamped
// on an Owner publish of a changed text, and the page the site's data license names that Carrel never
// takes down or moves. The write tests run Carrel's real code against site-api's reference site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it } from "vitest";

import { writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { readFields, splitSource } from "~/lib/frontmatter";
import { expandShared, legalTypeOf, prepareLegalWrite, sectionsUsed, type SharedSection } from "~/lib/legal";
import { deleteSection, listSections, saveSection } from "~/lib/legal.server";
import { requireSiteProject } from "~/lib/projects.server";
import { siteEntry } from "~/lib/sites.server";
import { action as legalAction, loader as legalLoader } from "~/routes/legal";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

const SECTIONS: SharedSection[] = [
  { key: "hosting", title: "Hosting", body: "{{site_name}} runs on Cloudflare. Questions go to {{contact}}." },
  { key: "analytics", title: "Analytics", body: "Cloudflare Web Analytics counts visits without tracking cookies." },
];

const FRONT = ["---", "path: /privacy", 'title: "Privacy"', "legal_type: privacy", 'site_name: "dustinedwards.info"', 'contact: "hello@example.test"', "---", ""].join("\n");

describe("expandShared", () => {
  it("writes each section between its markers with the page's fields filled in", () => {
    const out = expandShared("Intro.\n\n<!-- shared:hosting -->\n", SECTIONS, { site_name: "dustinedwards.info", contact: "hello@example.test" });
    expect(out.text).toBe(
      "Intro.\n\n<!-- shared:hosting -->\ndustinedwards.info runs on Cloudflare. Questions go to hello@example.test.\n<!-- /shared:hosting -->\n",
    );
    expect(out.unknownSections).toEqual([]);
    expect(out.missingFields).toEqual([]);
  });

  it("gives the same text when run again, so a page is expanded on every write", () => {
    const values = { site_name: "A", contact: "b@example.test" };
    const once = expandShared("<!-- shared:hosting -->\n\n<!-- shared:analytics -->\n", SECTIONS, values).text;
    expect(expandShared(once, SECTIONS, values).text).toBe(once);
    expect(sectionsUsed(once)).toEqual(["hosting", "analytics"]);
  });

  it("replaces text a person typed inside the markers, since the section is the source", () => {
    const out = expandShared("<!-- shared:analytics -->\nold wording\n<!-- /shared:analytics -->", SECTIONS, {});
    expect(out.text).not.toContain("old wording");
  });

  it("names an unknown section and a missing field, and leaves both as written", () => {
    const out = expandShared("<!-- shared:nope -->\n<!-- shared:hosting -->", SECTIONS, { site_name: "A" });
    expect(out.unknownSections).toEqual(["nope"]);
    expect(out.missingFields).toEqual(["contact"]);
    expect(out.text).toContain("<!-- shared:nope -->");
    expect(out.text).toContain("{{contact}}");
  });
});

describe("prepareLegalWrite", () => {
  const base = { sections: SECTIONS, today: "2026-10-06" };

  it("stamps last_updated when the Owner publishes a changed text", () => {
    const result = prepareLegalWrite({ ...base, source: `${FRONT}New.\n`, stored: `${FRONT}Old.\n`, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("leaves the date alone when only a field changed", () => {
    const stored = `${FRONT}Same.\n`;
    const result = prepareLegalWrite({ ...base, source: stored.replace("hello@example.test", "other@example.test"), stored, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("stamps a draft that goes public even if its text was already saved", () => {
    const stored = `${FRONT}Saved earlier.\n`;
    const result = prepareLegalWrite({ ...base, source: stored, stored, storedPublic: false, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("does not stamp a draft save, and keeps a missing field's token so no work is lost", () => {
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const result = prepareLegalWrite({ ...base, source, stored: null, storedPublic: false, public: false });
    expect(result.ok && result.source).toContain("{{contact}}");
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("refuses to go public with a field missing or a section unknown, and says which", () => {
    const missing = prepareLegalWrite({ ...base, source: FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n", stored: null, storedPublic: false, public: true });
    expect(!missing.ok && missing.message).toContain("contact");
    const unknown = prepareLegalWrite({ ...base, source: `${FRONT}<!-- shared:nope -->\n`, stored: null, storedPublic: false, public: true });
    expect(!unknown.ok && unknown.message).toContain('"nope"');
  });

  it("recognises a legal page by its legal_type", () => {
    expect(legalTypeOf(FRONT)).toBe("privacy");
    expect(legalTypeOf("---\ntitle: x\n---\n")).toBeNull();
    expect(legalTypeOf("no frontmatter")).toBeNull();
  });
});

let projectId: number;
let ownerId: number;

beforeEach(async () => {
  await resetDb();
  ownerId = await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  for (const s of SECTIONS) {
    await testEnv.DB.prepare("INSERT INTO legal_sections (key, title, body, updated_by) VALUES (?, ?, ?, ?)").bind(s.key, s.title, s.body, ownerId).run();
  }
});

async function as(email: string) {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, "read") };
}

async function seed(site: ReturnType<typeof fakeSite>, id: string, source: string) {
  const { viewer, project } = await as("owner@test.invalid");
  const saved = await writeToSite(connectedEnv(), project, viewer, id, { action: "save", source, expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  return saved.version;
}

const writes = (site: ReturnType<typeof fakeSite>) => site.requests.filter((r) => !r.startsWith("GET"));

describe("a legal page written to the site", () => {
  it("is published with its shared sections filled in and its date stamped, through the real write path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n\n<!-- shared:hosting -->\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version }, site.fetch);
    expect(published.ok).toBe(true);
    // A publish with no text sends the stored text, so the stored text is what the draft save wrote.
    const doc = await site.adapter.content.get("page.privacy");
    expect(doc?.source).toContain("dustinedwards.info runs on Cloudflare. Questions go to hello@example.test.");
    expect(doc?.status).toBe("published");
  });

  it("stamps last_updated when the text sent with a publish changed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source: `${FRONT}Changed.\n` }, site.fetch);
    expect(published.ok).toBe(true);
    expect(readFields(splitSource((await site.adapter.content.get("page.privacy"))!.source).front).last_updated).toBe(new Date().toISOString().slice(0, 10));
  });

  it("is refused at publish with a field missing, and the site hears no write after the seed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const version = await seed(site, "page.privacy", source);
    const before = writes(site).length;
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source }, site.fetch);
    expect(published).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
  });

  it("is an ordinary item for an AI session: no special refusal, the same role rules", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("editor@test.invalid");
    const saved = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "save", source: `${FRONT}Draft text.\n`, expectedVersion: null }, site.fetch, { client: "claude" });
    expect(saved.ok).toBe(true);
  });
});

describe("PLANT: the page the site's data license names", () => {
  const TERMS = ["---", "path: /terms", 'title: "Terms"', "legal_type: terms", "---", "The terms.", ""].join("\n");

  it("cannot be unpublished through Carrel, and the site hears nothing", async () => {
    expect(siteEntry("dustinedwards").keepPublic).toContain("page.terms");
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "publish", expectedVersion: version }, site.fetch);
    if (!published.ok) throw new Error(published.message);
    const before = writes(site).length;
    const result = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "unpublish", expectedVersion: published.version }, site.fetch);
    expect(result).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
    expect((await site.adapter.content.get("page.terms"))?.status).toBe("published");
  });

  it("can have its wording changed, but not its path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
    expect((moved as { message: string }).message).toContain("/terms");
    const reworded = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("The terms.", "Better terms."), expectedVersion: version }, site.fetch);
    expect(reworded.ok).toBe(true);
  });

  it("is guarded by id even when its legal_type is removed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("legal_type: terms\n", "").replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
  });
});

describe("the shared sections", () => {
  it("are changed only by the Owner", async () => {
    const editor = await as("editor@test.invalid");
    await expect(saveSection(testEnv.DB, editor.project, editor.viewer, { key: "x", title: "X", body: "Text." })).rejects.toMatchObject({ status: 403 });
    await expect(deleteSection(testEnv.DB, editor.project, "hosting")).rejects.toMatchObject({ status: 403 });
    const owner = await as("owner@test.invalid");
    expect(await saveSection(testEnv.DB, owner.project, owner.viewer, { key: "x", title: "X", body: "Text." })).toEqual({ ok: true });
    expect((await listSections(testEnv.DB)).map((s) => s.key)).toEqual(["analytics", "hosting", "x"]);
  });

  it("refuse a bad name, an empty text and a wide dash", async () => {
    const owner = await as("owner@test.invalid");
    for (const input of [
      { key: "Bad Name", title: "T", body: "B" },
      { key: "ok", title: "", body: "B" },
      { key: "ok", title: "T", body: "One — two." },
    ]) {
      expect((await saveSection(testEnv.DB, owner.project, owner.viewer, input)).ok).toBe(false);
    }
  });
});

describe("the Legal tab", () => {
  async function contextFor(email: string) {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env: connectedEnv(), ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor(email));
    context.set(nonceContext, "test-nonce");
    return context;
  }

  it("lists each legal page, says which are not set up, and flags a page behind the shared text", async () => {
    const site = fakeSite();
    const realFetch = globalThis.fetch;
    globalThis.fetch = site.fetch;
    try {
      await seed(site, "page.privacy", `${FRONT}<!-- shared:analytics -->\n`);
      // The shared text changes after the page was written to the site.
      await testEnv.DB.prepare("UPDATE legal_sections SET body = ? WHERE key = ?").bind("Newer wording.", "analytics").run();
      const data = (await legalLoader({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: new Request("https://carrel.test/p/de-info/legal") } as never)) as {
        pages: { type: string; setUp: boolean; behind?: boolean; shared?: string[] }[];
        canManage: boolean;
        sections: unknown[];
      };
      expect(data.pages.map((p) => [p.type, p.setUp])).toEqual([["privacy", true], ["terms", false]]);
      expect(data.pages[0]).toMatchObject({ behind: true, shared: ["analytics"] });
      expect(data.canManage).toBe(true);
      expect(data.sections).toHaveLength(2);
    } finally {
      globalThis.fetch = realFetch;
    }
  });

  it("changes a section only for the Owner, through the action", async () => {
    const body = new FormData();
    body.set("intent", "save-section");
    body.set("key", "hosting");
    body.set("title", "Hosting");
    body.set("body", "New text.");
    const request = () => new Request("https://carrel.test/p/de-info/legal", { method: "POST", body });
    const ok = await legalAction({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: request() } as never);
    expect(ok).toMatchObject({ saved: "hosting" });
    await expect(legalAction({ params: { project: SLUG }, context: await contextFor("editor@test.invalid"), request: request() } as never)).rejects.toMatchObject({ status: 403 });
  });
});

test/agent-keys.test.ts.source:
// Named agent keys at the AI door (job_77fd33040bdd). An agent that cannot complete OAuth (Grok Build)
// presents a key, and the key's Worker secret NAME is the agent: AGENT_KEY_GROK is "grok". The key
// says who is knocking and grants nothing: the agent is the person row "agent:grok" in People, its
// role comes from there, and it is credited as "agent:grok", never as Dustin. Every refusal below
// must end with nothing written, and each is planted in scripts/plant-gates.mjs or by hand (see the
// PR) and must turn the named test red.

import { createExecutionContext } from "cloudflare:test";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { agentPrincipal, keysMatch } from "~/lib/agent-keys.server";
import { addAgent, listPeople, PeopleRefusal, setProjectRole } from "~/lib/people-admin.server";
import { findAgentViewer } from "~/lib/people.server";
import { aiDoor } from "~/lib/mcp/door";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { MCP_HOST, modernRequest, readMessage, type ToolCallResult } from "./mcp-client";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const KEY = "grok-test-key-0123456789abcdefghijklmnop";
const OTHER_KEY = "other-test-key-0123456789abcdefghijklmnop";
const SLUG = "de-info";
const UNSHARED = "other-site";

let site: ReturnType<typeof fakeSite>;
let agentId: number;
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  agentId = await addPerson("agent:grok");
  projectId = await addProject(SLUG, "dustinedwards");
  await addProject(UNSHARED, "foxing");
  await share(projectId, agentId, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
});

afterEach(() => vi.unstubAllGlobals());

const env = (extra: Record<string, string> = {}): Env => connectedEnv({ AGENT_KEY_GROK: KEY, ...extra });

async function door(request: Request, e: Env = env()) {
  return aiDoor(request, e, createExecutionContext());
}

function authed(authorization: string | null, name: string, args: Record<string, unknown> = {}, headers: Record<string, string> = {}) {
  return modernRequest(3, "tools/call", { name, arguments: args }, { ...(authorization ? { Authorization: authorization } : {}), ...headers });
}

async function call(name: string, args: Record<string, unknown> = {}, opts: { key?: string; env?: Env; headers?: Record<string, string> } = {}) {
  const response = await door(authed(`Bearer ${opts.key ?? KEY}`, name, args, opts.headers), opts.env);
  if (response.status !== 200) return { status: response.status, result: undefined as ToolCallResult | undefined };
  return { status: 200, result: (await readMessage(response)).result as unknown as ToolCallResult };
}

async function seedPost() {
  return (await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nDustin's words.\n", expectedVersion: null, changeId: "seed" })).version;
}

const rows = async (sql: string) => (await testEnv.DB.prepare(sql).all()).results;

describe("what a named agent key does", () => {
  it("lets the agent read, save an AI draft beside Dustin's, flag and preview, credited as agent:grok", async () => {
    await seedPost();
    const listed = await call("list_projects");
    expect(listed.result!.structuredContent).toMatchObject({ projects: [{ slug: SLUG, role: "editor" }] });
    expect(((listed.result!.structuredContent as { projects: unknown[] }).projects).length).toBe(1);

    const saved = await call("save_draft", { project: SLUG, item: "post-one", source: "---\ntitle: Post one\n---\nGrok's try.\n", note: "A try." });
    expect(saved.result!.isError).toBeUndefined();
    expect(await rows("SELECT client, source FROM ai_drafts")).toEqual([{ client: "agent:grok", source: "---\ntitle: Post one\n---\nGrok's try.\n" }]);
    const owner = await viewerFor("owner@test.invalid");
    expect(await rows(`SELECT person_id FROM ai_drafts WHERE person_id = ${owner.id}`)).toEqual([]);
    expect(await rows(`SELECT person_id FROM ai_drafts WHERE person_id = ${agentId}`)).toHaveLength(1);

    const flagged = await call("add_finding", { project: SLUG, item: "post-one", message: "A flag." });
    expect(flagged.result!.structuredContent).toMatchObject({ flagged: true });
    expect(await rows("SELECT message FROM findings")).toEqual([{ message: "A flag. (from agent:grok)" }]);

    const preview = await call("preview", { project: SLUG, item: "post-one" });
    expect(preview.result!.isError).toBeUndefined();

    // Nothing reached the site's record: an agent's saved draft lives only in Carrel, and nothing is credited to Dustin.
    expect(await rows("SELECT id FROM changes")).toEqual([]);
    expect(site.requests.filter((r) => (r.startsWith("POST") || r.startsWith("PUT")) && !r.endsWith("/preview"))).toEqual([]);
  });

  it("PLANT: a key trying publish is refused with the Owner-only message, and nothing is published", async () => {
    const version = await seedPost();
    const { result } = await call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result).toMatchObject({ isError: true, content: [{ text: "Only the Owner's own sessions may publish." }] });
    expect((await site.adapter.content.get("post-one"))!.status).not.toBe("published");
    expect(await rows("SELECT * FROM ai_publications")).toEqual([]);
    expect(await rows("SELECT id FROM changes")).toEqual([]);
  });

  it("PLANT: the role is the person's role in People, never the key's: a Reader agent cannot save a draft", async () => {
    await seedPost();
    await testEnv.DB.prepare("UPDATE project_members SET role = 'reader' WHERE person_id = ?").bind(agentId).run();
    const { result } = await call("save_draft", { project: SLUG, item: "post-one", source: "x" });
    expect(result).toMatchObject({ isError: true, content: [{ text: "You may not write drafts on this project." }] });
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
  });

  it("PLANT: a project the agent has no role on is not there for it: not listed, not read, not drafted, not flagged", async () => {
    const { result: listed } = await call("list_projects");
    expect(JSON.stringify(listed!.structuredContent)).not.toContain(UNSHARED);
    for (const [name, args] of [
      ["search_items", {}],
      ["read_item", { item: "post-one" }],
      ["save_draft", { item: "post-one", source: "x" }],
      ["add_finding", { item: "post-one", message: "m" }],
      ["publish", { item: "post-one", expected_version: "v" }],
    ] as const) {
      const { result } = await call(name, { project: UNSHARED, ...args });
      expect(result, name).toMatchObject({ isError: true, content: [{ text: "Not found, or not shared with this person." }] });
    }
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
    expect(await rows("SELECT id FROM findings")).toEqual([]);
  });

  it("PLANT: a row marked Owner is never an agent: the key is refused", async () => {
    // The database allows one Owner, so the real one has to go before the agent's row can be flagged.
    await testEnv.DB.prepare("DELETE FROM people WHERE email = 'owner@test.invalid'").run();
    await testEnv.DB.prepare("UPDATE people SET is_owner = 1 WHERE email = 'agent:grok'").run();
    expect(await findAgentViewer(testEnv.DB, "grok")).toBeNull();
    expect((await call("list_projects")).status).toBe(403);
  });
});

describe("what a named agent key refuses", () => {
  it("PLANT: an unknown key is refused by the OAuth path: 401 with the Bearer challenge, nothing run", async () => {
    const response = await door(authed(`Bearer ${OTHER_KEY}`, "list_projects"));
    expect(response.status).toBe(401);
    expect(response.headers.get("WWW-Authenticate")).toContain("resource_metadata=");
    const near = await door(authed(`Bearer ${KEY}x`, "list_projects"));
    expect(near.status).toBe(401);
    const short = await door(authed(`Bearer ${KEY.slice(0, -1)}`, "list_projects"));
    expect(short.status).toBe(401);
  });

  it("PLANT: a key whose secret is absent is refused, and so is one that was revoked by deleting the secret", async () => {
    const without = connectedEnv();
    expect((await call("list_projects", {}, { env: without })).status).toBe(401);
    const revoked: Env = { ...env() };
    delete revoked.AGENT_KEY_GROK;
    expect((await call("list_projects", {}, { env: revoked })).status).toBe(401);
    // A blank secret admits nobody, and is not a key that matches the empty string.
    expect((await call("list_projects", {}, { env: env({ AGENT_KEY_GROK: "  " }), key: " " })).status).toBe(401);
  });

  it("PLANT: a key whose person row is disabled, or missing, is refused at once, and never falls through to OAuth", async () => {
    expect((await call("list_projects")).status).toBe(200);
    await testEnv.DB.prepare("UPDATE people SET disabled_at = '2026-10-07T00:00:00Z' WHERE email = 'agent:grok'").run();
    expect((await call("list_projects")).status).toBe(403);
    await testEnv.DB.prepare("DELETE FROM project_members").run();
    await testEnv.DB.prepare("DELETE FROM people WHERE email = 'agent:grok'").run();
    expect((await call("list_projects")).status).toBe(403);
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
  });

  it("PLANT: the agent's name is the secret's name, never the request's: a header or body naming another agent changes nothing", async () => {
    await addPerson("agent:other");
    await share(projectId, (await viewerFor("agent:other")).id, "editor");
    await seedPost();
    const claims = {
      "X-Agent": "other",
      "X-Agent-Name": "other",
      "X-Carrel-Agent": "agent:other",
      "X-Forwarded-User": "owner@test.invalid",
      "Cf-Access-Authenticated-User-Email": "owner@test.invalid",
      "Cf-Access-Jwt-Assertion": "x.y.z",
      "Mcp-Client": "agent:other",
    };
    const saved = await call("save_draft", { project: SLUG, item: "post-one", source: "x" }, { headers: claims });
    expect(saved.result!.isError).toBeUndefined();
    // A body that claims an identity is refused by the tool's own schema; nothing is written.
    for (const claim of [{ agent: "other" }, { client: "agent:other" }, { person: "owner@test.invalid" }]) {
      const refused = await door(authed(`Bearer ${KEY}`, "save_draft", { project: SLUG, item: "post-one", source: "y", ...claim }, claims));
      expect(JSON.stringify(await readMessage(refused)), JSON.stringify(claim)).toMatch(/error|invalid|unrecognized|additional/i);
    }
    expect(await rows("SELECT client FROM ai_drafts")).toEqual([{ client: "agent:grok" }]);
    // Two agents with two keys: each key is its own name, whichever the request claims to be.
    const second = await call("save_draft", { project: SLUG, item: "post-one", source: "z" }, { env: env({ AGENT_KEY_OTHER: OTHER_KEY }), key: OTHER_KEY, headers: { "X-Agent-Name": "grok" } });
    expect(second.result!.isError).toBeUndefined();
    expect((await rows("SELECT client FROM ai_drafts ORDER BY id")).map((r) => r.client)).toEqual(["agent:grok", "agent:other"]);
  });

  it("PLANT: a malformed Authorization header is never an agent: it goes to the OAuth path and is refused there", async () => {
    for (const header of [`Basic ${KEY}`, "Bearer", "Bearer ", `Bearer ${KEY} extra`, `Token ${KEY}`, KEY, `Bearer\t${KEY}`, ""]) {
      expect((await door(authed(header || null, "list_projects"))).status, header).toBe(401);
    }
    // The scheme is case-insensitive, as HTTP's is.
    expect((await door(authed(`bearer ${KEY}`, "list_projects"))).status).toBe(200);
  });

  it("is inert until a secret exists: with none, the door answers as it did before", async () => {
    const none = connectedEnv();
    expect(await agentPrincipal(none, `Bearer ${KEY}`)).toBeNull();
    const response = await door(modernRequest(1, "tools/list"), none);
    expect(response.status).toBe(401);
  });

  it("keeps the agent key to /mcp: another path on the door is never an agent's", async () => {
    for (const path of ["/", "/p/de-info", "/authorize", "/token", "/health"]) {
      const response = await door(new Request(`https://${MCP_HOST}${path}`, { headers: { Authorization: `Bearer ${KEY}` } }));
      if (path !== "/health") expect(response.status, path).toBeGreaterThanOrEqual(400);
      expect(await response.text(), path).not.toContain("projects");
    }
  });
});

describe("how the key is read", () => {
  it("names the agent from the secret's name, lower-cased, and only a valid name", async () => {
    expect(await agentPrincipal({ AGENT_KEY_GROK: KEY }, `Bearer ${KEY}`)).toBe("grok");
    expect(await agentPrincipal({ AGENT_KEY_Mixed_Case: KEY }, `Bearer ${KEY}`)).toBe("mixed_case");
    for (const name of ["AGENT_KEY_", "AGENT_KEY_has space", "AGENT_KEY_" + "x".repeat(33), "AGENT_KEY_-lead", "NOT_AGENT_KEY_GROK", "agent_key_grok"]) {
      expect(await agentPrincipal({ [name]: KEY }, `Bearer ${KEY}`), name).toBeNull();
    }
    expect(await agentPrincipal({ AGENT_KEY_GROK: 7 as unknown as string }, `Bearer 7`)).toBeNull();
  });

  it("picks the right agent among several and refuses a key that is none of them", async () => {
    const e = { AGENT_KEY_GROK: KEY, AGENT_KEY_OTHER: OTHER_KEY };
    expect(await agentPrincipal(e, `Bearer ${OTHER_KEY}`)).toBe("other");
    expect(await agentPrincipal(e, `Bearer ${KEY}`)).toBe("grok");
    expect(await agentPrincipal(e, "Bearer nope")).toBeNull();
    expect(await agentPrincipal(e, null)).toBeNull();
  });

  it("compares digests: equal keys match, and any difference in content or length does not", async () => {
    expect(await keysMatch(KEY, KEY)).toBe(true);
    expect(await keysMatch(KEY, `${KEY}x`)).toBe(false);
    expect(await keysMatch(KEY, KEY.slice(1))).toBe(false);
    expect(await keysMatch(KEY, OTHER_KEY)).toBe(false);
    expect(await keysMatch("", KEY)).toBe(false);
  });
});

describe("adding an agent in People", () => {
  it("is the Owner's alone, and the agent row is never an Owner or a reviewer, with no role until one is set", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const added = await addAgent(testEnv.DB, owner, { name: " Claude-Two ", label: "Claude Two" });
    expect(added).toMatchObject({ email: "agent:claude-two", name: "Claude Two", isOwner: false, isReviewer: false, roles: [] });
    expect(await findAgentViewer(testEnv.DB, "claude-two")).toMatchObject({ email: "agent:claude-two" });

    const editor = await addPerson("editor@test.invalid");
    await share(projectId, editor, "editor");
    await expect(addAgent(testEnv.DB, await viewerFor("editor@test.invalid"), { name: "sneaky" })).rejects.toMatchObject({ status: 404 });
    await expect(addAgent(testEnv.DB, await viewerFor("agent:grok"), { name: "sneaky" })).rejects.toMatchObject({ status: 404 });
    expect(await rows("SELECT email FROM people WHERE email = 'agent:sneaky'")).toEqual([]);
  });

  it("refuses a duplicate and a name that is not a name, and changes nothing", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const before = await rows("SELECT email FROM people");
    for (const name of ["grok", "GROK", "", "a b", "a@b.co", "-x", "x".repeat(33), "agent:x"]) {
      await expect(addAgent(testEnv.DB, owner, { name }), name).rejects.toBeInstanceOf(PeopleRefusal);
    }
    expect(await rows("SELECT email FROM people")).toEqual(before);
  });

  it("lists the agent and lets the Owner set its role like anyone's, Editor allowed", async () => {
    const owner = await viewerFor("owner@test.invalid");
    await addAgent(testEnv.DB, owner, { name: "fresh" });
    const fresh = (await viewerFor("agent:fresh")).id;
    await setProjectRole(testEnv.DB, owner, fresh, projectId, "editor");
    const { people } = await listPeople(testEnv.DB, owner);
    expect(people.find((p) => p.email === "agent:fresh")!.roles).toEqual([{ projectId, role: "editor" }]);
  });
});

test/content.test.ts.source:
// Planted problems for writes to a site (design section 7, "Access, roles, key"): a Reader saves, an
// Editor publishes, an Editor changes a live post, a non-member reads, and a stale expectedVersion.
// Each must be refused, and refused before the site is asked to change anything.

import { beforeEach, describe, expect, it } from "vitest";

import { autosave, readDraft, writeToSite } from "~/lib/content.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
});

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, action) };
}

/** A post already on the site, saved by the Owner, returned with its current version. */
async function seed(site: ReturnType<typeof fakeSite>, env: Env, status: "draft" | "published" = "draft") {
  const { viewer, project } = await as("owner@test.invalid");
  const saved = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# One\n", expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  if (status === "draft") return saved.version;
  const published = await writeToSite(env, project, viewer, "post-one", { action: "publish", expectedVersion: saved.version }, site.fetch);
  if (!published.ok) throw new Error(published.message);
  return published.version;
}

function writesTo(site: ReturnType<typeof fakeSite>) {
  return site.requests.filter((r) => !r.startsWith("GET"));
}

describe("PLANT: a non-member reads", () => {
  it("is answered 404, the same as a project that does not exist", async () => {
    const stranger = await viewerFor("stranger@test.invalid");
    expect(await refusal(requireSiteProject(testEnv.DB, stranger, SLUG, "read"))).toBe(404);
    expect(await refusal(requireSiteProject(testEnv.DB, stranger, "no-such-project", "read"))).toBe(404);
  });

  it("is answered 404 for a project that is not a site", async () => {
    await addProject("a-book");
    const owner = await viewerFor("owner@test.invalid");
    expect(await refusal(requireSiteProject(testEnv.DB, owner, "a-book", "read"))).toBe(404);
  });
});

describe("PLANT: a Reader saves", () => {
  it("is refused for autosave and for a save to the site, and the site hears nothing", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const { viewer, project } = await as("reader@test.invalid");
    expect(await refusal(autosave(env.DB, project, viewer, "post-one", { source: "x", baseVersion: null }))).toBe(403);
    expect(
      await refusal(writeToSite(env, project, viewer, "post-one", { action: "save", source: "x", expectedVersion: null }, site.fetch)),
    ).toBe(403);
    expect(site.requests).toEqual([]);
  });
});

describe("PLANT: an Editor publishes", () => {
  it("is refused for publish, schedule and unpublish before any request", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    site.requests.length = 0;
    const { viewer, project } = await as("editor@test.invalid");
    for (const request of [
      { action: "publish" as const, expectedVersion: version },
      { action: "schedule" as const, expectedVersion: version, publishAt: "2030-01-01T00:00:00Z" },
      { action: "unpublish" as const, expectedVersion: version },
    ]) {
      expect(await refusal(writeToSite(env, project, viewer, "post-one", request, site.fetch)), request.action).toBe(403);
    }
    expect(site.requests).toEqual([]);
  });

  it("is refused when the change would alter a live post, since that is a publish", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env, "published");
    site.requests.length = 0;
    const { viewer, project } = await as("editor@test.invalid");
    expect(
      await refusal(writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Changed live\n", expectedVersion: version }, site.fetch)),
    ).toBe(403);
    expect(writesTo(site)).toEqual([]);
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# One\n");
  });

  it("lets an Editor save a draft, and records who did it", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("editor@test.invalid");
    const outcome = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# One, edited\n", expectedVersion: version }, site.fetch);
    expect(outcome).toMatchObject({ ok: true, status: "draft" });
    const change = await testEnv.DB.prepare("SELECT person_id, action, version_before FROM changes WHERE id = ?")
      .bind(outcome.ok ? outcome.changeId : "")
      .first();
    expect(change).toEqual({ person_id: viewer.id, action: "save", version_before: version });
  });
});

describe("PLANT: a stale expectedVersion", () => {
  it("is refused by the site, reported as a conflict, and the person's draft is kept", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    // Someone else moves the post on.
    const moved = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Moved\n", expectedVersion: version }, site.fetch);
    expect(moved.ok).toBe(true);

    await autosave(env.DB, project, viewer, "post-one", { source: "# My edit\n", baseVersion: version });
    const stale = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# My edit\n", expectedVersion: version }, site.fetch);
    expect(stale).toMatchObject({ ok: false, reason: "conflict" });
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# Moved\n");
    expect((await readDraft(env.DB, project, viewer, "post-one"))?.source).toBe("# My edit\n");
  });

  it("refuses a create over a slug the site already holds", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    const clobber = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Clobber\n", expectedVersion: null }, site.fetch);
    expect(clobber).toMatchObject({ ok: false, reason: "conflict" });
  });
});

describe("the Owner's writes", () => {
  it("publish, index the result, record the change, and clear the draft that was sent", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    await autosave(env.DB, project, viewer, "post-one", { source: "# One, final\n", baseVersion: version });
    const outcome = await writeToSite(
      env,
      project,
      viewer,
      "post-one",
      { action: "publish", expectedVersion: version, source: "# One, final\n" },
      site.fetch,
    );
    expect(outcome).toMatchObject({ ok: true, status: "published" });
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# One, final\n");
    expect(await readDraft(env.DB, project, viewer, "post-one")).toBeNull();
    const indexed = await testEnv.DB.prepare("SELECT status, title FROM site_items WHERE project_id = ? AND item_id = ?")
      .bind(projectId, "post-one")
      .first();
    expect(indexed).toEqual({ status: "published", title: "One, final" });
    const count = await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM changes").first<{ n: number }>();
    expect(count!.n).toBe(2);
  });

  it("reports a site that is not connected rather than failing obscurely", async () => {
    const { viewer, project } = await as("owner@test.invalid");
    await expect(
      writeToSite(testEnv, project, viewer, "post-one", { action: "save", source: "x", expectedVersion: null }),
    ).rejects.toThrow(/No SITE_DUSTINEDWARDS_KEY set/);
  });
});

test/history.test.ts.source:
// The history screens, driven through the route's loader with a real request context: a Reader may
// read all of it, nothing in it writes (to the site or to Carrel), and each comparison names the
// right two texts, older first.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave, writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { orderPair } from "~/lib/history.server";
import { hasChanges, unifiedPatch } from "~/lib/patch";
import { requireSiteProject } from "~/lib/projects.server";
import { loader as historyLoader } from "~/routes/history";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let versions: string[];

const V1 = "---\ntitle: Post one\n---\nFirst words.\n";
const V2 = "---\ntitle: Post one\n---\nFirst words, revised.\n";
const V3 = "---\ntitle: Post one\n---\nFirst words, revised.\n\nA new closing paragraph.\n";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, reader, "reader");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
  const owner = await viewerFor("owner@test.invalid");
  const project = await requireSiteProject(testEnv.DB, owner, SLUG, "publish");
  versions = [];
  let expected: string | null = null;
  for (const source of [V1, V2, V3]) {
    const saved = await writeToSite(env, project, owner, "post-one", { action: "save", source, expectedVersion: expected }, site.fetch);
    if (!saved.ok) throw new Error(saved.message);
    expected = saved.version;
    versions.push(saved.version);
  }
  site.requests.length = 0;
});

async function load(email: string, search = "") {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one/history${search}`);
  return historyLoader({ request, params: { project: SLUG, item: "post-one" }, context } as never);
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

const changeRows = async () => (await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM changes").first<{ n: number }>())!.n;

describe("reading history", () => {
  it("lists the revisions newest first for a Reader, and only reads", async () => {
    const before = await changeRows();
    const data = await load("reader@test.invalid");
    expect(data.revisions.map((r) => r.version)).toEqual([...versions].reverse());
    expect(data.revisions).toHaveLength(3);
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
    expect(await changeRows()).toBe(before);
  });

  it("opens the source of an old revision", async () => {
    const data = await load("reader@test.invalid", `?version=${versions[0]}`);
    expect(data.view).toMatchObject({ kind: "source", source: V1, current: false, previous: null, newest: versions[2] });
    const newest = await load("reader@test.invalid", `?version=${versions[2]}`);
    expect(newest.view).toMatchObject({ kind: "source", source: V3, current: true, previous: versions[1], newest: null });
  });

  it("says plainly when the revision is not one the site holds", async () => {
    const data = await load("reader@test.invalid", "?version=nope");
    expect(data.view).toMatchObject({ kind: "problem", message: "The site has no such revision of this post." });
  });

  it("is answered 404 to someone with no role on the project, before the site is asked", async () => {
    expect(await refusal(load("stranger@test.invalid"))).toBe(404);
    expect(site.requests).toEqual([]);
  });
});

describe("comparing revisions", () => {
  it("sets the older revision against the newer whichever was picked first, from the site's own patch", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[2]}&v=${versions[0]}`);
    expect(data.picked).toEqual([versions[0], versions[2]]);
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-First words.\n");
    expect(patch).toContain("+First words, revised.\n");
    expect(patch).toContain("+A new closing paragraph.\n");
    expect(site.requests).toContain("GET /api/carrel/v1/content/post-one/diff");
  });

  it("by word, hands the two revisions' texts to the word compare, older as Before", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[0]}&v=${versions[1]}&by=word`);
    expect(data.view).toMatchObject({ kind: "compare", patch: null, before: { text: V1 }, after: { text: V2 } });
  });

  it("refuses one pick, the same pick twice and a pick the site does not hold, in words", async () => {
    for (const search of [`?v=${versions[0]}`, `?v=${versions[0]}&v=${versions[0]}`, `?v=${versions[0]}&v=nope`]) {
      const data = await load("reader@test.invalid", search);
      expect(data.view, search).toMatchObject({ kind: "problem", message: "Pick two different revisions to compare." });
    }
  });

  it("orders a pair by the site's list, newest first, so the older is always from", () => {
    const list = [
      { version: "c", at: "2026-10-03T00:00:00Z", author: "a", message: "" },
      { version: "b", at: "2026-10-02T00:00:00Z", author: "a", message: "" },
      { version: "a", at: "2026-10-01T00:00:00Z", author: "a", message: "" },
    ];
    expect(orderPair(list, ["c", "a"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a", "c"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a"])).toBeNull();
    expect(orderPair(list, ["a", "a"])).toBeNull();
    expect(orderPair(list, ["a", "z"])).toBeNull();
  });
});

describe("comparing the working draft", () => {
  async function ownDraft(source: string) {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "edit");
    await autosave(testEnv.DB, project, owner, "post-one", { source, baseVersion: versions[2]! });
    return { owner, project };
  }

  it("sets the draft against the site's text with a patch built here, and the site is only read", async () => {
    await ownDraft(V3.replace("A new closing paragraph.", "A different closing paragraph."));
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-A new closing paragraph.\n");
    expect(patch).toContain("+A different closing paragraph.\n");
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
  });

  it("says there is nothing to compare when the person has no working draft", async () => {
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view).toMatchObject({ kind: "problem" });
    expect((data.view as { message: string }).message).toMatch(/no working draft/);
  });

  it("sets the draft against an AI draft, and a draft that is not the viewer's is not found", async () => {
    const { owner, project } = await ownDraft(V3);
    const saved = await saveAiDraft(env, project, { viewer: owner, client: "Claude Code" }, "post-one", { source: V3.replace("First words, revised.", "First words, tightened."), note: "" }, site.fetch);
    const data = await load("owner@test.invalid", `?compare=ai&ai=${saved.id}`);
    const view = data.view as { kind: string; heading: string; patch: string };
    expect(view.kind).toBe("compare");
    expect(view.heading).toContain("AI draft from Claude Code");
    expect(view.patch).toContain("-First words, revised.\n");
    expect(view.patch).toContain("+First words, tightened.\n");
    expect(await refusal(load("reader@test.invalid", `?compare=ai&ai=${saved.id}`))).toBe(404);
  });
});

describe("the local patch", () => {
  it("names both sides but one file, shows only the changed lines with context, and says nothing changed when nothing did", () => {
    const patch = unifiedPatch("post-one.md", { text: "a\nb\nc\nd\ne\nf\ng\nh\n", label: "On the site" }, { text: "a\nb\nc\nD\ne\nf\ng\nh\n", label: "Your draft" });
    expect(patch).toContain("--- post-one.md\tOn the site");
    expect(patch).toContain("+++ post-one.md\tYour draft");
    expect(patch).toContain("-d\n+D\n");
    expect(hasChanges(patch)).toBe(true);
    const same = unifiedPatch("post-one.md", { text: "same\n", label: "a" }, { text: "same\n", label: "b" });
    expect(hasChanges(same)).toBe(false);
  });
});

